use hs_loop::repl::ReplSession;use serde_json::{json,Value};static ENV:std::sync::Mutex<()>=std::sync::Mutex::new(());
#[test]fn configured_custom_skill_and_default_history_are_owned_by_session(){let _g=ENV.lock().unwrap_or_else(std::sync::PoisonError::into_inner);let d=tempfile::tempdir().unwrap();let root=d.path().join("custom");std::fs::create_dir(&root).unwrap();std::fs::write(root.join("alpha.md"),"---\nname: alpha\ndescription: A\n---\nFollow these exact private instructions.").unwrap();let cfg=d.path().join("rig");let script=d.path().join("script");std::fs::write(&script,"{\"tool\":\"skill\",\"args\":{\"name\":\"alpha\"}}\n{\"tool\":\"get_goal\",\"args\":{}}\n").unwrap();unsafe{std::env::set_var("HS_SEQMODEL_SCRIPT",&script)}std::fs::write(&cfg,format!("[skills]\nincludeDefaultRoots=false\ncustomSkillDirs=['{}']\n[[models]]\nname='scripted'\ncommand=['{}']\ndefault=true\n",root.display(),env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();let log=d.path().join("run");let mut s=ReplSession::load(&cfg,&log,false,Some(2)).unwrap();s.run_goal("Load alpha").unwrap();let r=hs_log::StreamReader::open(&log,s.stream_id()).unwrap();let v:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice::<Value>(&r.resolve_payload(e).ok()?).ok()).collect();assert!(v.iter().any(|v|v["plugin"]=="skill"&&v["result"]["content"]=="Follow these exact private instructions."));assert!(v.iter().filter_map(|v|v["messages"].as_array()).any(|m|m.iter().any(|m|m["role"]=="tool"&&m["content"].as_str().is_some_and(|s|s.starts_with("<skill_content name=\"alpha\">")))));assert!(v.iter().any(|v|v["record_type"]=="skill/catalog"&&v["entries"]==json!([{"name":"alpha","description":"A"}])));}
#[test]fn invalid_skill_root_configuration_fails_at_load(){let _g=ENV.lock().unwrap_or_else(std::sync::PoisonError::into_inner);let d=tempfile::tempdir().unwrap();let script=d.path().join("script");std::fs::write(&script,"{}\n").unwrap();unsafe{std::env::set_var("HS_SEQMODEL_SCRIPT",&script)}for setting in ["includeDefaultRoots='false'","customSkillDirs=[1]","unknownSetting=true"]{let cfg=d.path().join("rig");std::fs::write(&cfg,format!("[skills]\n{setting}\n[[models]]\nname='scripted'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();assert!(ReplSession::load(&cfg,&d.path().join("run"),false,Some(1)).is_err(),"{setting}");}}
#[test]fn resumed_default_session_retains_loaded_skill_instructions(){let _g=ENV.lock().unwrap_or_else(std::sync::PoisonError::into_inner);let d=tempfile::tempdir().unwrap();let root=d.path().join("custom");std::fs::create_dir(&root).unwrap();std::fs::write(root.join("alpha.md"),"---\nname: alpha\ndescription: A\n---\nDurable loaded instruction.").unwrap();let cfg=d.path().join("rig");let script=d.path().join("script");std::fs::write(&script,"{\"tool\":\"skill\",\"args\":{\"name\":\"alpha\"}}\n").unwrap();unsafe{std::env::set_var("HS_SEQMODEL_SCRIPT",&script)}std::fs::write(&cfg,format!("[skills]\nincludeDefaultRoots=false\ncustomSkillDirs=['{}']\n[[models]]\nname='scripted'\ncommand=['{}']\ndefault=true\n",root.display(),env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();let log=d.path().join("run");let mut s=ReplSession::load(&cfg,&log,false,Some(1)).unwrap();s.run_goal("Load alpha").unwrap();let id=s.stream_id();drop(s);std::fs::write(&script,"{\"tool\":\"get_goal\",\"args\":{}}\n").unwrap();let mut s=ReplSession::load_resume(&cfg,&log,false,Some(1),id).unwrap();s.run_goal("Continue").unwrap();let r=hs_log::StreamReader::open(&log,id).unwrap();let calls:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice::<Value>(&r.resolve_payload(e).ok()?).ok()).filter(|v|v["messages"].is_array()).collect();let last=calls.last().unwrap();assert!(last["messages"].as_array().unwrap().iter().any(|m|m["role"]=="tool"&&m["content"].as_str().is_some_and(|s|s.contains("Durable loaded instruction."))));}
#[test]fn restored_inner_loop_has_skill_history_even_without_repl_memory_override(){let _g=ENV.lock().unwrap_or_else(std::sync::PoisonError::into_inner);let d=tempfile::tempdir().unwrap();let project=d.path().join("project");let bundle=project.join(".dsh/skills/alpha");std::fs::create_dir_all(&bundle).unwrap();std::fs::write(bundle.join("SKILL.md"),"---\nname: alpha\ndescription: A\n---\nRestored alpha instructions.").unwrap();let cfg=d.path().join("rig");let script=d.path().join("script");std::fs::write(&script,"{\"tool\":\"skill\",\"args\":{\"name\":\"alpha\"}}\n").unwrap();unsafe{std::env::set_var("HS_SEQMODEL_SCRIPT",&script)}std::fs::write(&cfg,format!("[[models]]\nname='scripted'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();let log=d.path().join("run");let mut lp=hs_loop::InnerLoop::new(hs_kernel::Kernel::load(&cfg).unwrap(),&log,false,1).unwrap();lp.set_answer_root(Some(project.clone()));lp.run_root_human_mission("load","Load alpha").unwrap();let id=lp.stream_id();drop(lp);std::fs::write(&script,"{\"tool\":\"get_goal\",\"args\":{}}\n").unwrap();let mut lp=hs_loop::InnerLoop::with_stream(hs_kernel::Kernel::load(&cfg).unwrap(),&log,id,false,1).unwrap();lp.set_answer_root(Some(project));lp.run_mission_resuming("continue","Continue").unwrap();let r=hs_log::StreamReader::open(&log,id).unwrap();let calls:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice::<Value>(&r.resolve_payload(e).ok()?).ok()).filter(|v|v["messages"].is_array()).collect();assert!(calls.last().unwrap()["messages"].as_array().unwrap().iter().any(|m|m["role"]=="tool"&&m["content"].as_str().is_some_and(|s|s.contains("Restored alpha instructions."))));}
#[test]fn direct_invocation_survives_resume_and_source_file_removal(){let _g=ENV.lock().unwrap_or_else(std::sync::PoisonError::into_inner);let d=tempfile::tempdir().unwrap();let project=d.path().join("project");let bundle=project.join(".dsh/skills/alpha");std::fs::create_dir_all(&bundle).unwrap();let path=bundle.join("SKILL.md");std::fs::write(&path,"---\nname: alpha\ndescription: A\ndisable-model-invocation: true\n---\nPreserve direct instructions verbatim.").unwrap();let cfg=d.path().join("rig");let script=d.path().join("script");std::fs::write(&script,"{\"tool\":\"get_goal\",\"args\":{}}\n").unwrap();unsafe{std::env::set_var("HS_SEQMODEL_SCRIPT",&script)}std::fs::write(&cfg,format!("[[models]]\nname='scripted'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();let log=d.path().join("run");let mut lp=hs_loop::InnerLoop::new(hs_kernel::Kernel::load(&cfg).unwrap(),&log,false,1).unwrap();lp.set_answer_root(Some(project.clone()));lp.run_root_human_mission("direct","/alpha").unwrap();let id=lp.stream_id();drop(lp);std::fs::remove_file(path).unwrap();let mut lp=hs_loop::InnerLoop::with_stream(hs_kernel::Kernel::load(&cfg).unwrap(),&log,id,false,1).unwrap();lp.set_answer_root(Some(project));lp.run_mission_resuming("continue","Continue").unwrap();let r=hs_log::StreamReader::open(&log,id).unwrap();let values:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();assert_eq!(values.iter().filter(|v|v["record_type"]=="skill/invocation").count(),1);let last=values.iter().filter(|v|v["messages"].is_array()).last().unwrap();assert!(last["messages"].as_array().unwrap().iter().any(|m|m["role"]=="user"&&m["content"].as_str().is_some_and(|s|s.contains("Preserve direct instructions verbatim."))));}
